/**
 * Injects PWA + iOS metadata into the exported web shell.
 *
 * Expo only uses app/+html.tsx when statically rendering (output: 'static').
 * RepBook exports as 'single' — dynamic routes like /log/[day]/[week] cannot be
 * pre-rendered — so the shell is generated by Expo and has to be patched here.
 *
 * Runs as part of `npm run build:web`. Idempotent.
 */
import { readFileSync, writeFileSync } from 'node:fs';

const FILE = 'dist/index.html';
const MARKER = 'repbook-web-meta';

const TAGS = `
    <!-- ${MARKER} -->
    <meta name="description" content="Beat last week. Week-over-week gym tracking." />
    <meta name="theme-color" content="#101113" />
    <link rel="manifest" href="/manifest.json" />
    <link rel="apple-touch-icon" href="/icon.png" />
    <meta name="apple-mobile-web-app-capable" content="yes" />
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
    <meta name="apple-mobile-web-app-title" content="RepBook" />
    <style>html, body { background-color: #101113; }</style>
`;

let html = readFileSync(FILE, 'utf8');

if (html.includes(MARKER)) {
  console.log('web shell already patched');
  process.exit(0);
}

// viewport-fit=cover keeps the layout under the iPhone notch/home indicator.
html = html.replace(
  '<meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no" />',
  '<meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no, viewport-fit=cover" />',
);

html = html.replace('</head>', `${TAGS}  </head>`);

writeFileSync(FILE, html);
console.log('patched dist/index.html with PWA + iOS metadata');
